  群青: { cost: 8, type: 'mag', target: 'enemies', power: 27, element: '水', desc: '比金子還貴的藍色，從很遠很遠的東方來。水屬性全體攻擊。' },
  明暗: { cost: 7, type: 'debuff', target: 'enemies', buff: { stat: 'res', mult: 0.75, turns: 3 }, desc: '亮的地方更亮，暗的地方更暗。全體敵人的定大幅下降。' },
  紅十字: { cost: 4, type: 'phy', target: 'enemy', power: 1.6, element: '金', desc: '舉著紅色的十字架，往前衝。金屬性強力一擊。' },
  挨家挨戶: { cost: 6, type: 'phy', target: 'enemies', power: 0.85, element: '金', desc: '一扇門、一扇門地敲過去。金屬性全體攻擊。' },
  頌歌: { cost: 7, type: 'buff', target: 'allies', buff: { stat: 'atk', mult: 1.25, turns: 3 }, desc: '孩子們一邊走，一邊唱。全隊的力提升。' },
