  利息: { cost: 0, type: 'debuff', target: 'enemies', buff: { stat: 'atk', mult: 0.75, turns: 3 }, desc: '借一個金幣，要還一個半。全體的力大幅下降。' },
  燭淚: { cost: 0, type: 'mag', target: 'enemy', power: 34, element: '火', status: '褪色', chance: 0.35, desc: '教堂裡的蠟燭，燒了一整夜。' },
  滾落: { cost: 0, type: 'phy', target: 'enemies', power: 1.15, element: '金', desc: '從大門上被拆下來的紅球，滾了一整條街。' },
  六顆球: { cost: 0, type: 'debuff', target: 'enemies', buff: { stat: 'def', mult: 0.7, turns: 3 }, desc: '金色的盾牌上，六顆圓圓的球。全體的守大幅下降。' },
  劍臨: { cost: 0, type: 'phy', target: 'enemy', power: 2.0, element: '金', desc: '「看哪，劍要很快、很快地落在地上。」' },
