  越過山脈: { cost: 0, type: 'phy', target: 'enemies', power: 1.15, element: '金', desc: '「會有一個人，越過阿爾卑斯山而來。」' },
  惶惶: { cost: 0, type: 'debuff', target: 'enemies', buff: { stat: 'spd', mult: 0.7, turns: 3 }, desc: '城門關了。大家都在等。全體的疾大幅下降。' },
