  十日: { cost: 0, type: 'mag', target: 'enemy', power: 36, element: '木', status: '迷惘', chance: 0.35, desc: '十個年輕人，在城外躲瘟疫，講了一百個故事。' },
  高燒: { cost: 0, type: 'mag', target: 'enemies', power: 33, element: '陰', status: '褪色', chance: 0.35, desc: '那一年春天，城裡又有人發燒了。' },
  七層: { cost: 0, type: 'debuff', target: 'enemies', buff: { stat: 'res', mult: 0.7, turns: 3 }, desc: '一層、一層、又一層，堆到比房子還高。全體的定大幅下降。' },
