  丟石頭: { cost: 0, type: 'phy', target: 'enemy', power: 2.0, element: '土', desc: '一顆石頭，從人群裡飛出來。' },
  敲鐘: { cost: 0, type: 'debuff', target: 'enemies', buff: { stat: 'def', mult: 0.7, turns: 3 }, desc: '修道院的鐘，一直響、一直響。全體的守大幅下降。' },
  驟雨: { cost: 0, type: 'mag', target: 'enemies', power: 35, element: '水', desc: '天忽然暗了下來，下了一陣大雨。' },
