  走過去: { cost: 0, type: 'phy', target: 'enemy', power: 2.1, element: '火', desc: '兩排火堆的中間，只有一條很窄很窄的路。' },
  證明: { cost: 0, type: 'mag', target: 'enemies', power: 34, element: '火', status: '迷惘', chance: 0.3, desc: '「如果他說的是真的，就證明給我們看。」' },
  等了一整天: { cost: 0, type: 'debuff', target: 'enemies', buff: { stat: 'spd', mult: 0.7, turns: 3 }, desc: '從中午等到天黑。全體的疾大幅下降。' },
