  迸裂: { cost: 4, type: 'phy', target: 'enemy', power: 1.6, element: '土', desc: '黑曜石的刀刃，薄得透光，也利得可怕。土屬性強力一擊。' },
  擲矛器: { cost: 6, type: 'phy', target: 'enemies', power: 0.85, element: '土', desc: '用一根木頭的擲矛器，把短矛甩出去。土屬性全體攻擊。' },
  紅與黑: { cost: 7, type: 'buff', target: 'allies', buff: { stat: 'res', mult: 1.3, turns: 3 }, desc: '「擁有紅與黑的人」，就是有智慧的人。全隊的定提升。' },
  蜂鳥: { cost: 5, type: 'mag', target: 'enemy', power: 41, element: '火', desc: '蜂鳥的羽毛，在光下面一下綠、一下紫。火屬性單體攻擊。' },
