  一顆一顆: { cost: 0, type: 'debuff', target: 'enemies', buff: { stat: 'atk', mult: 0.75, turns: 3 }, desc: '一顆一顆地數可可豆。全體的力大幅下降。' },
  金光: { cost: 0, type: 'mag', target: 'enemies', power: 34, element: '金', status: '迷惘', chance: 0.35, desc: '看到金子的人，眼睛都亮了起來。' },
  搶金: { cost: 0, type: 'phy', target: 'enemy', power: 2.0, element: '金', desc: '金子做的旗子、金子做的項鍊，一把搶過去。' },
