  哭泣的女人: { cost: 0, type: 'debuff', target: 'enemies', buff: { stat: 'spd', mult: 0.7, turns: 3 }, desc: '「夜裡，有一個女人在哭：我的孩子們，我們要走了。」全體的疾大幅下降。' },
