  冷光: { cost: 0, type: 'phy', target: 'enemy', power: 2.05, element: '金', desc: '鐵，是這裡的人從來沒有見過的金屬。冷冷的，亮亮的。' },
  柯巴煙: { cost: 0, type: 'mag', target: 'enemy', power: 38, element: '火', status: '迷惘', chance: 0.35, desc: '燒柯巴樹脂的白煙，香香的，濃得看不見前面。' },
  關門: { cost: 0, type: 'debuff', target: 'enemies', buff: { stat: 'spd', mult: 0.65, turns: 3 }, desc: '廣場的每一道門，都被關上了。全體的疾大幅下降。' },
