  空的廣場: { cost: 0, type: 'debuff', target: 'enemies', buff: { stat: 'res', mult: 0.65, turns: 3 }, desc: '第二天早上，廣場上什麼都沒有了。全體的定大幅下降。' },
  回音: { cost: 0, type: 'heal', target: 'self', power: 230, desc: '鼓停了。可是牆壁還在回音。' },
