  缺口: { cost: 0, type: 'phy', target: 'enemies', power: 1.2, element: '土', desc: '堤道上的橋，被拆掉了。只剩下一個一個的缺口。' },
  蔓延: { cost: 0, type: 'mag', target: 'enemies', power: 37, element: '陰', status: '褪色', chance: 0.4, desc: '從一個人，到一家人，到一整條街。' },
