  沒有人照顧: { cost: 0, type: 'mag', target: 'enemy', power: 43, element: '陰', status: '失語', chance: 0.4, desc: '一家人都病倒了。沒有人能起來，煮一碗粥。' },
  不分敵我: { cost: 0, type: 'phy', target: 'enemies', power: 1.2, element: '陰', desc: '病，不管你是哪一邊的。' },
