  千秋硯: { cat: '器物誌', fact: '虛構', vol: '序卷',
    text: '巴掌大小的紫石硯，硯池中央有一道細如髮絲的裂痕，墨在其中會像潮水一樣自己流動。以它研出的「時墨」書寫，可以進入文字所記載的時空。傳說是倉頡造字時，落在人間的第一滴墨。' },
